pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Start with the primary goal: minimize residual space (Best Fit)
    let mut score = post_residual as f64;

    // 1. Adaptive New-Bin Logic:
    // Heavily penalize opening new bins unless necessary, but adjust pressure 
    // based on the remaining item stream density.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let new_bin_penalty = 180.0 + (1.0 - progress) * 120.0;
        if fitting_bins_count > 0 {
            score += new_bin_penalty;
        } else {
            // Strong incentive to open a bin when it's the only choice
            score -= 85.0;
        }
    }

    // 2. Lookahead Optimization:
    // Refined lookahead: prioritize bins that leave exactly the size of the next item (perfect fit).
    // Penalize fragmentation (slack) more aggressively as we approach the end of the stream.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 75.0; 
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.45; 
        } else {
            // Penalize blocking the next item significantly if we have many open bins.
            score += 65.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)) * (open_bins_count as f64 / 10.0).sqrt();
        }
    }

    // 3. Dynamic Residual Balancing:
    // Instead of simple deviation, weight the penalty by the current mean_residual 
    // to force the bin towards the global average efficiency.
    let target_fit = (post_residual as f64 - mean_residual).abs();
    score += target_fit * 0.85;

    // 4. Density Balancing:
    // Prefer bins that are already "committed" to keep open_bins_count low.
    // Use an exponential curve to prioritize filling near-full bins.
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= (fullness * 25.0).powf(1.1);

    // 5. Fragmentation Mitigation:
    // If the post_residual is very small (< 10% of capacity), it creates "dead space".
    // Heavily penalize this to force consolidation.
    if post_residual > 0 && post_residual < (bin_capacity / 10) {
        score += 50.0;
    }

    // 6. Tie-breaker:
    // If this is the only bin that fits, reward it to finalize the placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals < 10) which are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Class Logic: Favor residuals that are multiples of common item sizes (20, 25, 33).
    // This helps align future items into the remaining space.
    let harmonic_penalty = (post_residual % 20) as f64 + (post_residual % 25) as f64;
    score += harmonic_penalty * 0.5;

    // 3. Lookahead Logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // 4. Pressure Management: If we are running low on bins or at the end of the stream,
    // be more aggressive about filling existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if we have plenty of fitting options.
        score += (fitting_bins_count as f64 * 15.0) + (progress * 50.0);
    }

    // 5. Balance the mean residual: Avoid creating bins that are significantly 
    // emptier than the current average to maintain uniform density.
    if post_residual > (mean_residual as u32) {
        score += (post_residual as f64 - mean_residual) * 0.2;
    }

    score
}
